CREATE MATERIALIZED VIEW non_leaf_771 AS
SELECT n.id AS n_id, n.name AS n_name, n.imdb_index AS n_imdb_index, n.imdb_id AS n_imdb_id, n.gender AS n_gender, n.name_pcode_cf AS n_name_pcode_cf, n.name_pcode_nf AS n_name_pcode_nf, n.surname_pcode AS n_surname_pcode, n.md5sum AS n_md5sum, ci.id AS ci_id, ci.person_id AS ci_person_id, ci.movie_id AS ci_movie_id, ci.person_role_id AS ci_person_role_id, ci.note AS ci_note, ci.nr_order AS ci_nr_order, ci.role_id AS ci_role_id, rt.id AS rt_id, rt.role AS rt_role, kt.id AS kt_id, kt.kind AS kt_kind, t.id AS t_id, t.title AS t_title, t.imdb_index AS t_imdb_index, t.kind_id AS t_kind_id, t.production_year AS t_production_year, t.imdb_id AS t_imdb_id, t.phonetic_code AS t_phonetic_code, t.episode_of_id AS t_episode_of_id, t.season_nr AS t_season_nr, t.episode_nr AS t_episode_nr, t.series_years AS t_series_years, t.md5sum AS t_md5sum, mi1.id AS mi1_id, mi1.movie_id AS mi1_movie_id, mi1.info_type_id AS mi1_info_type_id, mi1.info AS mi1_info, mi1.note AS mi1_note, it1.id AS it1_id, it1.info AS it1_info
FROM name AS n, cast_info AS ci, role_type AS rt, kind_type AS kt, title AS t, movie_info AS mi1, info_type AS it1
WHERE n.id = ci.person_id AND n.name ~~* '%ashl%' AND ci.movie_id = t.id AND ci.role_id = rt.id AND rt.role IN ('actor', 'actress', 'cinematographer', 'composer', 'costume designer') AND t.kind_id = kt.id AND kt.kind IN ('tv series', 'video game', 'video movie') AND t.id = mi1.movie_id AND mi1.info_type_id = it1.id AND mi1.info IN ('Dolby Digital', 'Stereo', 'UK', 'USA') AND it1.id IN ('6', '8}'::integ');